\documentclass[border=10pt]{standalone}
\usepackage{pgfplots}
\pgfplotsset{width=10cm, compat=1.18}
\usepackage{ctex}

\begin{document}

\begin{tikzpicture}
\begin{axis}[
    title={\textbf{我国近五年出生人口统计}},
    xlabel={年份},
    ylabel={出生人口（万人）},
    xmin=2018.5, xmax=2023.5,
    ymin=800, ymax=1600,
    xtick={2019,2020,2021,2022,2023},
    xticklabels={2019年,2020年,2021年,2022年,2023年},
    ytick={800,900,1000,1100,1200,1300,1400,1500,1600},
    grid=both,
    grid style={gray!30},
    legend pos=north west,
    font=\small,
    axis lines=left,
    every axis plot/.append style={line width=1.5pt},
    every node/.append style={font=\small},
    title style={yshift=0.5cm, font=\large\bfseries},
    label style={font=\large},
    tick label style={font=\large},
]

% 添加数据点
\addplot+[
    blue,
    mark=*,
    mark size=3pt,
    nodes near coords,
    nodes near coords align={above},
    point meta=explicit symbolic,
    every node near coord/.append style={
        font=\small,
        /pgf/number format/fixed,
        /pgf/number format/precision=0
    }
] coordinates {
    (2019, 1465) [1465万]
    (2020, 1200) [1200万]
    (2021, 1062) [1062万]
    (2022, 956)  [956万]
    (2023, 902)  [902万]
};

\end{axis}

% 添加说明注释
\begin{scope}[shift={(current axis.south west)}, yshift=-1cm]
\node[align=left, text width=8cm, font=\small] at (0,0) {
数据来源：国家统计局\\
\textit{备注：出生人口呈持续下降趋势}
};
\end{scope}

\end{tikzpicture}

\end{document}
